// Each trigger writes only its own row, so the loop needs no atomics.
void tcyc_cpu(const GraphView& g, const Params& p, std::span<const std::uint32_t> triggers, BlockOut& out, int chunk) {
  const std::int64_t count = std::int64_t(triggers.size());
  std::uint64_t saturated = 0;
  if (p.reach_prune) {  // reach pruning (SPEC v2 §8 S6): one search scratch per thread
    #pragma omp parallel reduction(+ : saturated)
    {
      ReachScratch reach(g.n);
      #pragma omp for schedule(dynamic, chunk)
      for (std::int64_t i = 0; i < count; ++i) {
        const std::uint32_t e = triggers[std::size_t(i)];
        RowSink sink = out.sink(e);
        tcyc_trigger_reach(g, p, e, sink, reach);
        saturated += sink.saturated;
      }
    }
    out.saturated += saturated;
    return;
  }
  #pragma omp parallel for schedule(dynamic, chunk) reduction(+ : saturated)
  for (std::int64_t i = 0; i < count; ++i) {
    const std::uint32_t e = triggers[std::size_t(i)];
    RowSink sink = out.sink(e);
    tcyc_trigger(g, p, e, sink);
    saturated += sink.saturated;
  }
  out.saturated += saturated;
}

